use lin::{Cell,Db,Row,SyncMode};
use lin::persist::{Pack,LogRecord,append_record,for_each_wal_frame};
use std::{fs,io::Seek,path::PathBuf,sync::atomic::{AtomicUsize,Ordering}};
struct Temp(PathBuf);
impl Temp {fn new()->Self{static N:AtomicUsize=AtomicUsize::new(0);let p=std::env::temp_dir().join(format!("lin-delete-key-{}-{}",std::process::id(),N.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&p).unwrap();Self(p)}}
impl Drop for Temp {fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn row()->Row{Row::from([("id".into(),Cell::from_text("a")),("uri".into(),Cell::from_text("u:a")),("body".into(),Cell::from_text("retained full body")),("embedding".into(),Cell::Vec(vec![0.25,-0.0].into()))])}
fn encoded(root:&Temp,name:&str,record:&LogRecord,sync:SyncMode)->Vec<u8>{let path=root.0.join(name);let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&path).unwrap();let mut bytes=0;append_record(&mut f,record,&mut Vec::new(),sync,&mut bytes).unwrap();assert_eq!(f.stream_position().unwrap(),bytes);drop(f);fs::read(path).unwrap()}
fn decoded(bytes:&[u8])->LogRecord{let mut out=Vec::new();assert_eq!(for_each_wal_frame(bytes,|r|{out.push(r);Ok(())}).unwrap(),1);out.pop().unwrap()}
#[test]fn full_projects_only_wire_delete_normal_keeps_original_rows(){let t=Temp::new();let rec=LogRecord{r#gen:9,next_id:77,pack:Pack::Delete{collection:"docs".into(),rows:vec![row()]}};let before=rmp_serde::to_vec_named(&rec).unwrap();let full=encoded(&t,"full",&rec,SyncMode::Full);let normal=encoded(&t,"normal",&rec,SyncMode::Normal);assert!(full.len()<normal.len());assert_eq!(rmp_serde::to_vec_named(&decoded(&normal)).unwrap(),before);let compact=decoded(&full);assert_eq!(compact.r#gen,9);assert_eq!(compact.next_id,77);let Pack::Delete{rows,..}=compact.pack else{panic!()};assert_eq!(rows[0].len(),2);assert_eq!(rows[0]["id"].text(),Some("a"));assert_eq!(rows[0]["uri"].text(),Some("u:a"));assert_eq!(rmp_serde::to_vec_named(&rec).unwrap(),before);}
#[test]fn canonical_oversize_delete_rejected_before_projection_or_file_write(){let t=Temp::new();let path=t.0.join("quota");let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&path).unwrap();let mut large=row();large.insert("body".into(),Cell::from_text("x".repeat(17*1024*1024)));let rec=LogRecord{r#gen:1,next_id:2,pack:Pack::Delete{collection:"docs".into(),rows:vec![large]}};let mut bytes=123;let error=append_record(&mut f,&rec,&mut Vec::new(),SyncMode::Full,&mut bytes).unwrap_err();assert!(error.to_string().contains("16MiB"));assert_eq!(bytes,123);assert_eq!(f.metadata().unwrap().len(),0);assert_eq!(f.stream_position().unwrap(),0);}
#[test]fn mixed_batch_keeps_update_bits_and_deep_batch_falls_back(){let t=Temp::new();let update=Pack::Update{collection:"docs".into(),rows:vec![row()]};let deletion=Pack::Delete{collection:"docs".into(),rows:vec![row()]};let rec=LogRecord{r#gen:1,next_id:2,pack:Pack::Batch{packs:vec![update.clone(),Pack::Batch{packs:vec![deletion.clone()]}]}};let got=decoded(&encoded(&t,"mixed",&rec,SyncMode::Full));let Pack::Batch{packs}=got.pack else{panic!()};assert_eq!(rmp_serde::to_vec_named(&packs[0]).unwrap(),rmp_serde::to_vec_named(&update).unwrap());let mut deep=deletion;for _ in 0..18{deep=Pack::Batch{packs:vec![deep]};}let rec=LogRecord{r#gen:3,next_id:4,pack:deep};assert_eq!(rmp_serde::to_vec_named(&decoded(&encoded(&t,"deep",&rec,SyncMode::Full))).unwrap(),rmp_serde::to_vec_named(&rec).unwrap());}
#[test]fn real_delete_retains_output_rollback_indexes_and_reopen(){let t=Temp::new();let dbpath=t.0.join("db");let mut db=Db::open(&dbpath).unwrap();db.run(r#"insert docs [{id:"a",uri:"u:a",body:"retained alpha",wing:"rag"},{id:"b",uri:"u:b",body:"retained beta",wing:"rag"}]"#).unwrap();db.run("index docs [wing]").unwrap();let held=db.run(r#"docs|id=="a""#).unwrap();let original=rmp_serde::to_vec_named(&held.rows).unwrap();let before=rmp_serde::to_vec_named(db.store.collection("docs")).unwrap();let generation=db.store.r#gen;{let mut tx=db.transaction().unwrap();let result=tx.run(r#"delete docs[id=="a"] cas each"#).unwrap();assert_eq!(rmp_serde::to_vec_named(&result.rows).unwrap(),original);tx.rollback().unwrap();}assert_eq!(db.store.r#gen,generation);assert_eq!(rmp_serde::to_vec_named(db.store.collection("docs")).unwrap(),before);let result=db.run(r#"delete docs[id=="a"] cas each"#).unwrap();assert_eq!(rmp_serde::to_vec_named(&result.rows).unwrap(),original);assert_eq!(rmp_serde::to_vec_named(&held.rows).unwrap(),original);assert_eq!(db.run(r#"docs|wing=="rag"|count"#).unwrap().rows[0]["hits"].as_int(),Some(1));assert!(db.run(r#"docs|search lex "alpha""#).unwrap().rows.is_empty());let expected=rmp_serde::to_vec_named(db.store.collection("docs")).unwrap();let expected_generation=db.store.r#gen;drop(db);let mut db=Db::open(&dbpath).unwrap();assert_eq!(db.store.r#gen,expected_generation);assert_eq!(rmp_serde::to_vec_named(db.store.collection("docs")).unwrap(),expected);assert!(db.store.get_by_id("docs","a").is_none());assert!(db.store.get_by_uri("u:a").is_none());assert_eq!(db.run(r#"docs|wing=="rag"|count"#).unwrap().rows[0]["hits"].as_int(),Some(1));}
